  if (!f || !f.coupon) return { code: 'MARKET', linha: 'Exclusive coupons, tap to copy' };
  var pct = parseInt(f.discount, 10) || 0;
  return {
    code: String(f.coupon).toUpperCase(),
    linha: f.name + (pct ? ' ' + pct + '% OFF' : '') + ', tap to copy'
  };
}

